#include <iostream>
#include <iomanip>
#include <string>

class PhoneNumber {
    friend std::ostream& operator<<(std::ostream& output, const PhoneNumber& number);
    friend std::istream& operator>>(std::istream& input, PhoneNumber& number);

private:
    std::string areaCode; // 3-digit area code
    std::string exchange; // 3-digit exchange
    std::string line;     // 4-digit line
};

// Overloaded stream insertion operator (non-member friend)
std::ostream& operator<<(std::ostream& output, const PhoneNumber& number) {
    output << "(" << number.areaCode << ") "
           << number.exchange << "-" << number.line;
    return output; // Enables cascading
}

// Overloaded stream extraction operator (non-member friend)
std::istream& operator>>(std::istream& input, PhoneNumber& number) {
    // Consume any leading whitespace/newlines between inputs, then ignore '('
    input >> std::ws;
    input.ignore();                         // skip '('
    input >> std::setw(3) >> number.areaCode; // read area code
    input.ignore(2);                        // skip ") "
    input >> std::setw(3) >> number.exchange; // read exchange
    input.ignore();                         // skip '-'
    input >> std::setw(4) >> number.line;     // read line
    return input; // Enables cascading
}

int main() {
    PhoneNumber p1;
    PhoneNumber p2;

    // Input cascaded: reads (800) 555-1212 then (212) 555-0199
    if (std::cin >> p1 >> p2) {
        std::cout << "Phone 1: " << p1 << "\n";
        std::cout << "Phone 2: " << p2 << "\n";
    }
    return 0;
}

body.vi:
Một toán tử một ngôi (ví dụ toán tử phủ định logic `!`) có thể được nạp chồng dưới dạng phương thức thành viên không tĩnh (non-static member function) không nhận đối số nào. Hàm này bắt buộc phải là non-static để có thể truy xuất dữ liệu thành viên của đối tượng đang được thao tác thông qua con trỏ ngầm định `this`.

Khi trình biên dịch bắt gặp biểu thức `!s` (với `s` là một đối tượng của lớp `MyString`), nó sẽ chuyển biểu thức này thành lời gọi phương thức `s.operator!()`. Nếu phương thức này chỉ kiểm tra trạng thái của đối tượng (chẳng hạn kiểm tra đối tượng chuỗi có rỗng hay không) mà không làm thay đổi các biến thành viên, phương thức nên được đánh dấu là `const`:
```cpp
class MyString {
public:
    bool operator!() const;
};
```

body.en:
A unary operator (such as the logical NOT operator `!`) can be overloaded as a non-static member function taking no arguments. Member operator functions must be non-static so that they can access the calling object's member data via the implicit `this` pointer.

When the compiler encounters `!s` (where `s` is an instance of `MyString`), it translates the expression into the member function call `s.operator!()`. If the operator merely inspects the object (e.g., checking whether a custom string is empty) without modifying its state, it should be declared `const`:
```cpp
class MyString {
public:
    bool operator!() const;
};
```

example.code:
#include <iostream>
#include <string>

class Container {
private:
    std::string data;

public:
    Container(const std::string& str = "") : data(str) {}

    // Unary operator! overloaded as a member function
    // Returns true if container is empty
    bool operator!() const {
        return data.empty();
    }

    const std::string& get() const { return data; }
};

int main() {
    Container emptyBox;
    Container filledBox("Antigravity");

    // Evaluates via emptyBox.operator!()
    if (!emptyBox) {
        std::cout << "emptyBox is empty.\n";
    }

    if (!filledBox) {
        std::cout << "filledBox is empty.\n";
    } else {
        std::cout << "filledBox contains: " << filledBox.get() << "\n";
    }

    return 0;
}
